// ── Utils: cálculo de permanencia ─────────────────────────────
const clasificar = (tipo, esRuta) => {
  if (esRuta || ["Examen de certificación","Certificación","Material de estudio"].includes(tipo))
    return "Certificaciones y exámenes";
  if (tipo === "Curso o capacitación") return "Cursos y capacitaciones";
  if (["Diplomado","Programa especializado"].includes(tipo)) return "Diplomados o programas especializados";
  return "Revisar";
};

const calcPlazo = (clasif, v) => {
  if (v < 60) return "N/A";
  if (clasif === "Certificaciones y exámenes") return "36 meses";
  if (clasif === "Cursos y capacitaciones") {
    if (v <= 500) return "12 meses"; if (v <= 1500) return "24 meses";
    if (v <= 4000) return "36 meses"; return "Anexo especial";
  }
  if (v <= 1500) return "24 meses"; if (v <= 4000) return "36 meses"; return "Anexo especial";
};

const calcModal = (clasif) =>
  clasif === "Certificaciones y exámenes" ? "Reintegro escalonado especial" : "Reintegro proporcional mensual";

const mesesEntre = (ini, sal) => {
  const a = new Date(ini), b = new Date(sal);
  return Math.max(0, (b.getFullYear() - a.getFullYear()) * 12 + (b.getMonth() - a.getMonth()));
};

const pctReintegro = (meses, clasif) => {
  if (clasif === "Certificaciones y exámenes") {
    if (meses <= 12) return 100; if (meses <= 24) return 50;
    if (meses <= 36) return 25;  return 0;
  }
  return Math.max(0, Math.round((36 - meses) / 36 * 100));
};

const roiLabel = (inv, ub) => {
  if (inv <= 0) return "Sin inversión"; if (ub <= 0) return "Sin forecast";
  return Math.round((ub - inv) / inv * 100) + "%";
};
const roiBadgeCls = (inv, ub) => !inv ? "rb-z" : !ub ? "rb-z" : ((ub-inv)/inv*100) >= 100 ? "rb-h" : "rb-p";
const pad3 = (n) => String(n).padStart(3, "0");

