// TAB 4: DESVINCULACIÓN
// ═══════════════════════════════════════════════════════════════
function TabDesvinculacion() {
  const [query, setQuery]       = useState("");
  const [acOpen, setAcOpen]     = useState(false);
  const [colab, setColab]       = useState(null);
  const [fecha, setFecha]       = useState(new Date().toISOString().split("T")[0]);
  const [resultado, setResultado] = useState(null);
  const acRef = useRef(null);

  useEffect(() => {
    const h = (e) => { if (acRef.current && !acRef.current.contains(e.target)) setAcOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  const sugs = COLAB_DEMO.filter(c => c.n.toLowerCase().includes(query.toLowerCase())).slice(0, 8);

  const calcular = () => {
    if (!colab || !fecha) return;
    const anexos = HIST_DEMO.filter(h => h.col === colab.n);
    let total = 0;
    const cards = anexos.map(a => {
      if (a.costo < 60) return { a, clasif:"Sin obligación", plazo:"N/A", meses:0, pct:0, val:0, cr:false, est:"Sin obligación (costo < $60)" };
      const meses = mesesEntre(colab.ing, fecha);
      const pct   = pctReintegro(meses, "Certificaciones y exámenes");
      const val   = Math.round(a.costo * pct) / 100;
      total += val;
      return { a, clasif:"Certificaciones y exámenes", plazo:"36 meses", meses, pct, val, cr:val>0, est: pct===0 ? "Devengado totalmente" : `Devengación pendiente (${pct}%)` };
    });
    setResultado({ colab, total, cards });
  };

  return (
    <>
      <div className="desv-intro">
        <h2>💼 Cálculo de Reintegro por Desvinculación</h2>
        <p>Calcula el monto que debe reintegrar el colaborador por capacitaciones cuya permanencia no fue devengada.</p>
      </div>

      <div className="desv-form">
        <div className="fl ac-wrap" ref={acRef}>
          <label className="lbl">Colaborador (activos y retirados)</label>
          <input className="inp" value={query} placeholder="Buscar por nombre..."
            onChange={e => { setQuery(e.target.value); setAcOpen(true); if (!e.target.value) setColab(null); }}
            onFocus={() => query && setAcOpen(true)} autoComplete="off" />
          {acOpen && sugs.length > 0 && (
            <ul className="ac-list">
              {sugs.map(c => (
                <li key={c.c} className="ac-item" onClick={() => { setColab(c); setQuery(c.n); setAcOpen(false); setResultado(null); }}>
                  <strong>{c.n}</strong>
                  <small>{c.cargo} · <span className={`est-b ${c.est.toLowerCase()}`}>{c.est}</span></small>
                </li>
              ))}
            </ul>
          )}
        </div>
        <div className="fl">
          <label className="lbl">Fecha de salida</label>
          <input type="date" className="inp" value={fecha} onChange={e => setFecha(e.target.value)} />
        </div>
        <button className="btn primary" style={{alignSelf:"flex-end"}} onClick={calcular}>🧮 Calcular</button>
      </div>

      {colab && (
        <div className="col-info">
          <span><strong>Cédula:</strong> {colab.c}</span>
          <span><strong>Cargo:</strong> {colab.cargo}</span>
          <span><strong>Empresa:</strong> {colab.emp}</span>
          <span><strong>Estado:</strong> <span className={`badge ${colab.est==="ACTIVO"?"green":"red"}`}>{colab.est}</span></span>
          <span><strong>Ingreso:</strong> {colab.ing}</span>
          <span><strong>Anexos:</strong> {HIST_DEMO.filter(h=>h.col===colab.n).length || "⚠ Sin anexos"}</span>
        </div>
      )}

      {resultado && (
        <>
          <div className="result-hdr">
            <div>
              <div style={{fontSize:10,color:"var(--text2)",textTransform:"uppercase",letterSpacing:".4px",marginBottom:3}}>Total a reintegrar</div>
              <div className={`total-val ${resultado.total>0?"rojo":"verde"}`}>${resultado.total.toFixed(2)}</div>
            </div>
            <div className="result-meta">
              <span>{resultado.cards.length} anexo(s) evaluado(s)</span>
              <span>{resultado.cards.filter(c=>c.val>0).length} con obligación de reintegro</span>
            </div>
            <button className="btn navy" onClick={() => alert("En producción: exporta el detalle en .txt para liquidaciones")}>
              📥 Exportar liquidación
            </button>
          </div>
          {resultado.cards.map((x, i) => (
            <div key={i} className={`dcard ${x.cr?"cr":"dev"}`}>
              <div className="dc-hdr">
                <span className="dc-marca">{x.a.marca}</span>
                <span className="dc-curso">{x.a.curso}</span>
                <span className={`dc-monto${x.cr?" al":""}`}>${x.val.toFixed(2)}</span>
              </div>
              <div className="dc-body">
                {[["Valor base",`$${x.a.costo}`],["Clasificación",x.clasif],["Plazo",x.plazo],
                  ["Meses transcurridos",x.meses],["% Reintegro",`${x.pct}%`],["Estado",x.est]
                ].map(([l,v]) => (
                  <div key={l} className="di"><label>{l}</label><span>{v}</span></div>
                ))}
              </div>
            </div>
          ))}
        </>
      )}
    </>
  );
}

