// TAB 5: DASHBOARD ROI
// ═══════════════════════════════════════════════════════════════
function TabROI() {
  const [vista, setVista] = useState("marca");
  const data = ROI_DEMO[vista] || [];
  const isMarca = vista === "marca", isPersona = vista === "persona";
  const totInv  = data.reduce((s,r) => s+r.inv, 0);
  const totC    = data.reduce((s,r) => s+r.c,   0);
  const COL_LBL = { marca:"Marca", persona:"Colaborador", area:"Área", departamento:"Departamento", cargo:"Cargo" };

  return (
    <div className="roi-wrap">
      {/* Strip principal */}
      <div className="roi-strip">
        <div>
          <div style={{fontSize:10,fontWeight:700,letterSpacing:"1.5px",textTransform:"uppercase",color:"var(--amber)"}}>ROI Global de Capacitación · DOS S.A. 2026</div>
          <div className="roi-big">214%</div>
          <div className="roi-formula">Fórmula: (Utilidad Bruta del Pipeline − Inversión Total) ÷ Inversión Total × 100</div>
        </div>
        <div className="roi-meta-row">
          {[["$5,820","Inversión Total DOS","#fcd34d"],["$18,300","Utilidad Bruta Pipeline","#34d399"],["47","Capacitaciones","#f9a8d4"],["31","Personas formadas","#c4b5fd"]].map(([v,l,c])=>(
            <React.Fragment key={l}>
              <div style={{textAlign:"center"}}>
                <div className="roi-stat-val" style={{color:c}}>{v}</div>
                <div className="roi-stat-lab">{l}</div>
              </div>
              {l !== "Personas formadas" && <div className="roi-div" />}
            </React.Fragment>
          ))}
        </div>
      </div>

      {/* KPI cards */}
      <div className="kgrid">
        {[["blue","$5,820","Inversión Total DOS"],["green","$18,300","Utilidad Bruta Estimada"],["amber","47","Capacitaciones registradas"],["teal","31","Colaboradores formados"]].map(([cl,v,l])=>(
          <div key={l} className={`kcard ${cl}`}><div className="kval">{v}</div><div className="klab">{l}</div></div>
        ))}
      </div>

      {/* Vista selector */}
      <div className="vtabs-dark">
        {["marca","persona","area","departamento","cargo"].map(v => (
          <button key={v} className={`vtd${vista===v?" on":""}`} onClick={() => setVista(v)}>
            {COL_LBL[v]}
          </button>
        ))}
      </div>

      <div className="note-dark">
        <span style={{fontSize:15,flexShrink:0}}>⚠</span>
        <div>Los datos de <strong>Utilidad Bruta Estimada</strong> provienen de la hoja "Base Forecast" del archivo ROI_Sistema_Integrado_2026.xlsx. Una vez conectada la base de datos, el ROI se calcula en tiempo real desde la vista <code style={{background:"rgba(0,0,0,.2)",padding:"1px 5px",borderRadius:3,fontSize:10}}>v_roi_por_marca</code>.</div>
      </div>

      <div className="rtbl-wrap">
        <table className="rtbl">
          <thead>
            <tr>
              <th>{COL_LBL[vista]}</th>
              {isPersona && <th>Detalle</th>}
              {!isPersona && <th className="tr">Personas</th>}
              <th className="tr">Capacitaciones</th>
              <th className="tr">Inversión DOS ($)</th>
              <th className="tr">ROI</th>
            </tr>
          </thead>
          <tbody>
            {data.map((r,i) => (
              <tr key={i}>
                <td>{isMarca ? <span className={`bc-tag ${MARCAS_BRAND[r.n]||"bc-otros"}`}>{r.n}</span> : r.n}</td>
                {isPersona  && <td style={{color:"var(--muted)",fontSize:11}}>{r.e}</td>}
                {!isPersona && <td className="tr" style={{color:"var(--soft)"}}>{r.p}</td>}
                <td className="tr" style={{color:"var(--soft)"}}>{r.c}</td>
                <td className="tr" style={{color:"#93c5fd",fontFamily:"var(--mono)"}}>${r.inv.toLocaleString("es-EC",{minimumFractionDigits:2})}</td>
                <td className="tr"><span className={`rb ${roiBadgeCls(r.inv,r.ub)}`}>{roiLabel(r.inv,r.ub)}</span></td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <td><strong>TOTAL</strong></td>
              {isPersona  && <td />}
              {!isPersona && <td />}
              <td className="tr">{totC}</td>
              <td className="tr" style={{fontFamily:"var(--mono)"}}>${totInv.toLocaleString("es-EC",{minimumFractionDigits:2})}</td>
              <td />
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
}

