// TAB 6: HISTORIAL
// ═══════════════════════════════════════════════════════════════
function TabHistorial() {
  const [q, setQ] = useState("");
  const data = q
    ? HIST_DEMO.filter(h =>
        h.col.toLowerCase().includes(q.toLowerCase()) ||
        h.marca.toLowerCase().includes(q.toLowerCase()) ||
        h.curso.toLowerCase().includes(q.toLowerCase()))
    : HIST_DEMO;
  const total = data.reduce((s,h) => s+h.costo, 0);

  return (
    <>
      <div className="hist-toolbar" style={{display:"flex",gap:12,alignItems:"center",marginBottom:14}}>
        <input className="hist-search" placeholder="🔍 Buscar por nombre, marca o curso..."
          value={q} onChange={e => setQ(e.target.value)} />
        <span style={{fontSize:12,color:"var(--text2)",whiteSpace:"nowrap"}}>{data.length} registros</span>
      </div>
      <div className="tbl-wrap">
        <table className="htbl">
          <thead>
            <tr>
              <th>N.° Registro</th><th>Colaborador</th><th>Empresa</th>
              <th>Marca</th><th>Capacitación</th><th>Fecha</th>
              <th style={{textAlign:"right"}}>Costo DOS</th><th>Conv.</th><th>PDF</th>
            </tr>
          </thead>
          <tbody>
            {data.map(h => (
              <tr key={h.reg}>
                <td style={{fontFamily:"var(--mono)",fontSize:11,color:"var(--red)",fontWeight:700}}>{h.reg}</td>
                <td style={{fontWeight:500}}>{h.col}</td>
                <td>{h.emp}</td>
                <td><span className="badge navy">{h.marca}</span></td>
                <td style={{maxWidth:200,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",fontSize:12}}>{h.curso}</td>
                <td style={{fontSize:12}}>{h.fecha}</td>
                <td style={{textAlign:"right",fontWeight:600}}>{h.costo > 0 ? `$${h.costo.toFixed(2)}` : "—"}</td>
                <td><span className={`badge ${h.conv?"green":"red"}`}>{h.conv?"Sí":"No"}</span></td>
                <td>{h.pdf
                  ? <a href="#" onClick={e=>e.preventDefault()} style={{fontSize:12,color:"var(--navy)",fontWeight:600}}>Ver PDF</a>
                  : <span style={{fontSize:11,color:"var(--text2)"}}>Pendiente</span>}
                </td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <td colSpan={6}><strong>TOTAL</strong></td>
              <td style={{textAlign:"right"}}>${total.toFixed(2)}</td>
              <td colSpan={2} />
            </tr>
          </tfoot>
        </table>
      </div>
    </>
  );
}

