// COMPONENTES AUXILIARES
// ═══════════════════════════════════════════════════════════════

/** Campo de solo lectura (autocompletado desde BASE_DATOS) */
function RoField({ label, value }) {
  return (
    <div className="fl">
      <label className="lbl">{label}</label>
      <div className={`ro ${value ? "ok" : "empty"}`}>
        {value || "Se autocompleta al seleccionar"}
      </div>
    </div>
  );
}

/** Campo imprimible */
function Pf({ label, v, hi }) {
  return (
    <div className="pf">
      <label>{label}</label>
      <span className={hi ? "hi" : ""}>{v || "—"}</span>
    </div>
  );
}

/** Toggle Sí/No genérico */
function Toggle({ label, value, onChange, opts }) {
  return (
    <div className="fl">
      <label className="lbl">{label}</label>
      <div className="tgl">
        {opts.map(o => (
          <button key={String(o.v)} className={value === o.v ? "on" : ""} onClick={() => onChange(o.v)}>
            {o.l}
          </button>
        ))}
      </div>
    </div>
  );
}
